file_editor: {"command": "create", "path": "/app/workspace/src/main/java/clusterdata/datatypes/TaskEvent.java", "file_text": "package clusterdata.datatypes;

import java.io.Serializable;

/**
 * Task events from the Google cluster-usage traces.
 *
 * CSV columns (v2.1):
 * 0: time (microseconds)
 * 1: missing info
 * 2: job ID
 * 3: task index
 * 4: machine ID
 * 5: event type
 * 6: user
 * 7: scheduling class
 * 8: priority
 * 9: CPU request
 * 10: memory request
 * 11: disk space request
 * 12: different machines restriction
 */
public class TaskEvent implements Serializable {

    // Event types (per trace schema)
    public static final int EVENT_SUBMIT = 0;

    public long timeMicros;
    public String missingInfo;
    public long jobId;
    public long taskIndex;
    public long machineId;
    public int eventType;
    public String user;
    public int schedulingClass;
    public int priority;
    public double cpuRequest;
    public double memoryRequest;
    public double diskSpaceRequest;
    public int differentMachinesRestriction;

    public TaskEvent() {
        // Flink POJO
    }

    public long getTimeMillis() {
        return timeMicros / 1000L;
    }

    public long getJobId() {
        return jobId;
    }

    public int getEventType() {
        return eventType;
    }

    public static TaskEvent fromCsvLine(String line) {
        String[] p = line.split(",", -1);
        if (p.length < 6) {
            throw new IllegalArgumentException("Invalid task_events line (expected >= 6 columns): " + line);
        }

        TaskEvent e = new TaskEvent();
        e.timeMicros = parseLong(p[0], 0L);
        e.missingInfo = emptyToNull(get(p, 1));
        e.jobId = parseLong(get(p, 2), -1L);
        e.taskIndex = parseLong(get(p, 3), -1L);
        e.machineId = parseLong(get(p, 4), -1L);
        e.eventType = (int) parseLong(get(p, 5), -1L);
        e.user = emptyToNull(get(p, 6));
        e.schedulingClass = (int) parseLong(get(p, 7), -1L);
        e.priority = (int) parseLong(get(p, 8), -1L);
        e.cpuRequest = parseDouble(get(p, 9), 0.0d);
        e.memoryRequest = parseDouble(get(p, 10), 0.0d);
        e.diskSpaceRequest = parseDouble(get(p, 11), 0.0d);
        e.differentMachinesRestriction = (int) parseLong(get(p, 12), 0L);
        return e;
    }

    private static String get(String[] parts, int idx) {
        return idx < parts.length ? parts[idx] : "";
    }

    private static String emptyToNull(String s) {
        if (s == null) {
            return null;
        }
        String t = s.trim();
        return t.isEmpty() ? null : t;
    }

    private static long parseLong(String s, long defaultValue) {
        String t = emptyToNull(s);
        if (t == null) {
            return defaultValue;
        }
        return Long.parseLong(t);
    }

    private static double parseDouble(String s, double defaultValue) {
        String t = emptyToNull(s);
        if (t == null) {
            return defaultValue;
        }
        return Double.parseDouble(t);
    }
}
