file_editor: {"command": "create", "path": "/app/workspace/src/main/java/clusterdata/io/GzipCsvSource.java", "file_text": "package clusterdata.io;

import org.apache.flink.streaming.api.functions.source.SourceFunction;

import java.io.BufferedReader;
import java.io.FileInputStream;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.Serializable;
import java.nio.charset.StandardCharsets;
import java.util.zip.GZIPInputStream;

/**
 * Simple single-file source for gzipped CSV files.
 *
 * This is intentionally minimal (no checkpointing), intended for bounded batch-style jobs.
 */
public class GzipCsvSource<T> implements SourceFunction<T>, Serializable {

    @FunctionalInterface
    public interface LineParser<T> extends Serializable {
        T parse(String line) throws Exception;
    }

    private final String path;
    private final LineParser<T> parser;

    private volatile boolean canceled = false;

    public GzipCsvSource(String path, LineParser<T> parser) {
        if (path == null) {
            throw new IllegalArgumentException("path must not be null");
        }
        if (parser == null) {
            throw new IllegalArgumentException("parser must not be null");
        }
        this.path = path;
        this.parser = parser;
    }

    @Override
    public void run(SourceContext<T> ctx) throws Exception {
        try (InputStream fis = new FileInputStream(path);
             InputStream is = path.endsWith(".gz") ? new GZIPInputStream(fis) : fis;
             BufferedReader br = new BufferedReader(new InputStreamReader(is, StandardCharsets.UTF_8))) {

            String line;
            while (!canceled && (line = br.readLine()) != null) {
                if (line.isEmpty()) {
                    continue;
                }
                T parsed = parser.parse(line);
                synchronized (ctx.getCheckpointLock()) {
                    ctx.collect(parsed);
                }
            }
        } catch (IOException ioe) {
            throw new RuntimeException("Failed reading input file: " + path, ioe);
        }
    }

    @Override
    public void cancel() {
        canceled = true;
    }
}
