file_editor: {"command": "create", "path": "/app/workspace/src/main/java/clusterdata/io/SingleFileSinkFunction.java", "file_text": "package clusterdata.io;

import org.apache.flink.configuration.Configuration;
import org.apache.flink.streaming.api.functions.sink.RichSinkFunction;

import java.io.BufferedWriter;
import java.io.File;
import java.io.FileOutputStream;
import java.io.OutputStreamWriter;
import java.nio.charset.StandardCharsets;

/**
 * Sink that writes all records into a single local file.
 *
 * Set sink parallelism to 1 when using this.
 */
public class SingleFileSinkFunction extends RichSinkFunction<String> {

    private final String outputPath;

    private transient BufferedWriter writer;

    public SingleFileSinkFunction(String outputPath) {
        this.outputPath = outputPath;
    }

    @Override
    public void open(Configuration parameters) throws Exception {
        File f = new File(outputPath);
        File parent = f.getParentFile();
        if (parent != null) {
            parent.mkdirs();
        }
        this.writer = new BufferedWriter(new OutputStreamWriter(new FileOutputStream(f, false), StandardCharsets.UTF_8));
    }

    @Override
    public synchronized void invoke(String value, Context context) throws Exception {
        writer.write(value);
        writer.newLine();
    }

    @Override
    public void close() throws Exception {
        if (writer != null) {
            writer.flush();
            writer.close();
        }
    }
}
