import java.io.BufferedReader;
import java.io.FileInputStream;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.Serializable;
import java.nio.charset.StandardCharsets;
import java.util.zip.GZIPInputStream;

/**
 * Bounded gzipped CSV source that assigns event-time timestamps and emits watermarks.
 *
 * This avoids Flink's legacy file monitoring sources (which can require additional JVM
 * --add-opens flags on newer Java versions).
 */
public class GzipCsvEventTimeSource<T> implements SourceFunction<T>, Serializable {

    @FunctionalInterface
    public interface LineParser<T> extends Serializable {
        T parse(String line) throws Exception;
    }

    @FunctionalInterface
    public interface TimestampAssigner<T> extends Serializable {
        long extractTimestampMillis(T value);
    }

    private final String path;
    private final LineParser<T> parser;
    private final TimestampAssigner<T> timestampAssigner;
    private final long outOfOrdernessMillis;
    private final int watermarkEveryN;

    private volatile boolean canceled = false;

    public GzipCsvEventTimeSource(
            String path,
            LineParser<T> parser,
            TimestampAssigner<T> timestampAssigner,
            long outOfOrdernessMillis,
            int watermarkEveryN) {
        if (path == null) {
            throw new IllegalArgumentException("path must not be null");
        }
        this.path = path;
        this.parser = parser;
        this.timestampAssigner = timestampAssigner;
        this.outOfOrdernessMillis = Math.max(0L, outOfOrdernessMillis);
        this.watermarkEveryN = Math.max(1, watermarkEveryN);
    }

    @Override
    public void run(SourceContext<T> ctx) throws Exception {
        long maxTimestamp = Long.MIN_VALUE;
        long records = 0L;

        try (InputStream fis = new FileInputStream(path);
             InputStream is = path.endsWith(".gz") ? new GZIPInputStream(fis) : fis;
             BufferedReader br = new BufferedReader(new InputStreamReader(is, StandardCharsets.UTF_8))) {

            String line;
            while (!canceled && (line = br.readLine()) != null) {
                if (line.isEmpty()) {
                    continue;
                }

                T parsed = parser.parse(line);
                long ts = timestampAssigner.extractTimestampMillis(parsed);
                if (ts > maxTimestamp) {
                    maxTimestamp = ts;
                }

                synchronized (ctx.getCheckpointLock()) {
                    ctx.collectWithTimestamp(parsed, ts);
                    records++;
                    if (records % watermarkEveryN == 0 && maxTimestamp != Long.MIN_VALUE) {
                        ctx.emitWatermark(new Watermark(maxTimestamp - outOfOrdernessMillis - 1L));
                    }
                }
            }

            synchronized (ctx.getCheckpointLock()) {
                // Final watermark to flush windows/timers.
                ctx.emitWatermark(Watermark.MAX_WATERMARK);
            }
        } catch (IOException ioe) {
            throw new RuntimeException("Failed reading input file: " + path, ioe);
        }
    }

    @Override
    public void cancel() {
        canceled = true;
    }
}
